using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class FinalCheck {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var group=root.Find("Sector01_CompletedArt");var doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(t=>Vector3.Distance(t.position,new Vector3(-15,-82,-10))<11).ToArray();var checks=new List<object>();
 foreach(var d in doors){Func<bool> blocked=()=>Physics.OverlapCapsule(d.position+Vector3.up*.34f,d.position+Vector3.up*1.48f,.28f,~0,QueryTriggerInteraction.Ignore).Any(c=>c.transform.IsChildOf(d)&&!c.name.Contains("Threshold"));Physics.SyncTransforms();bool openClear=!blocked();var moved=new Dictionary<Transform,Vector3>();foreach(var mf in d.GetComponentsInChildren<MeshFilter>())if(mf.name.StartsWith("Leaf_")||mf.name.StartsWith("Seal_")){var t=mf.transform;moved[t]=t.position;float side=Mathf.Sign(d.InverseTransformPoint(mf.GetComponent<Renderer>().bounds.center).x);t.position-=d.right*side*1.22f;}Physics.SyncTransforms();bool closedBlocks=blocked();foreach(var kv in moved)kv.Key.position=kv.Value;Physics.SyncTransforms();checks.Add(new{d.name,openClear,closedBlocks});}
 var state=new{scene=s.path,sector="C01",newInstances=group.childCount,doors=checks,instances=group.Cast<Transform>().Select(t=>new{t.name,asset=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject),position=new[]{t.position.x,t.position.y,t.position.z},rotation=new[]{t.eulerAngles.x,t.eulerAngles.y,t.eulerAngles.z},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z}}).ToArray(),oldProps=root.Find("Existing_Props_FirstPass").Cast<Transform>().Select(t=>new{t.name,active=t.gameObject.activeSelf,position=t.position.ToString(),rotation=t.eulerAngles.ToString()}).ToArray(),oldLights=root.GetComponentsInChildren<Light>(true).Where(l=>!l.transform.IsChildOf(group)).Select(l=>new{l.name,l.enabled,l.intensity,l.range,position=l.transform.position.ToString()}).ToArray(),player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player")).transform.position.ToString(),background=Application.runInBackground};
 File.WriteAllText(R+"/Docs/검수/2026-11-06_B5_Sector01/final_state.json",JsonConvert.SerializeObject(state,Formatting.Indented));EditorSceneManager.OpenScene(s.path);
 var sv=SceneView.lastActiveSceneView;if(sv){var target=new Vector3(-15.5f,-80.4f,-9.5f);var pos=new Vector3(-14.4f,-80.35f,-12.9f);sv.LookAt(target,Quaternion.LookRotation(target-pos),2.1f,false,true);sv.sceneLighting=true;sv.Repaint();}
 return new{state.scene,state.newInstances,doors=checks,state.player,state.background};}
}
